using Marketplace.Domain.Common; namespace Marketplace.Domain.Finance; public sealed class SellerBalance:AggregateRoot<long>{private SellerBalance(){}public long SellerId{get;private set;}public long AvailableIRR{get;private set;}public long PendingIRR{get;private set;}public long BlockedIRR{get;private set;}public long ReservedForSettlementIRR{get;private set;}public long LiabilityIRR{get;private set;}public DateTime UpdatedAtUtc{get;private set;}public long WithdrawableIRR=>Math.Max(0,AvailableIRR-ReservedForSettlementIRR);public static SellerBalance Create(long id,long sellerId)=>new(){Id=id,SellerId=sellerId,UpdatedAtUtc=DateTime.UtcNow};public void AddPending(long a){Positive(a);PendingIRR+=a;Touch();}public void ReleasePending(long a){Positive(a);if(a>PendingIRR)throw new DomainException("Insufficient pending balance.");PendingIRR-=a;AvailableIRR+=a;Touch();}public void AddAvailable(long a){Positive(a);AvailableIRR+=a;Touch();}public void RemoveAvailable(long a){Positive(a);if(a>AvailableIRR-ReservedForSettlementIRR)throw new DomainException("Insufficient withdrawable balance.");AvailableIRR-=a;Touch();}public void Block(long a){Positive(a);if(a>AvailableIRR-ReservedForSettlementIRR)throw new DomainException("Insufficient withdrawable balance.");AvailableIRR-=a;BlockedIRR+=a;Touch();}public void ReleaseBlock(long a){Positive(a);if(a>BlockedIRR)throw new DomainException("Insufficient blocked balance.");BlockedIRR-=a;AvailableIRR+=a;Touch();}public void ConsumeBlock(long a){Positive(a);if(a>BlockedIRR)throw new DomainException("Insufficient blocked balance.");BlockedIRR-=a;Touch();}public void ReserveForSettlement(long a){Positive(a);if(a>AvailableIRR-ReservedForSettlementIRR)throw new DomainException("Insufficient withdrawable balance.");ReservedForSettlementIRR+=a;Touch();}public void CompleteSettlement(long a){Positive(a);if(a>ReservedForSettlementIRR||a>AvailableIRR)throw new DomainException("Invalid settlement amount.");ReservedForSettlementIRR-=a;AvailableIRR-=a;Touch();}public void FailSettlement(long a){Positive(a);if(a>ReservedForSettlementIRR)throw new DomainException("Invalid settlement amount.");ReservedForSettlementIRR-=a;Touch();}public void AddLiability(long a){Positive(a);LiabilityIRR+=a;Touch();}public void RepayLiability(long a){Positive(a);if(a>LiabilityIRR)throw new DomainException("Liability repayment exceeds liability.");LiabilityIRR-=a;Touch();}private static void Positive(long a){if(a<=0)throw new DomainException("Amount must be positive.");}private void Touch()=>UpdatedAtUtc=DateTime.UtcNow;}
